<script setup lang="ts">
import {computed} from 'vue'
import type {SnmpResult} from '../tools/snmp'
const props=defineProps<{en:boolean;data:SnmpResult|null;error?:{code:string;message:string}}>(),t=(zh:string,en:string)=>props.en?en:zh
const latest=computed(()=>props.data?.interface_samples[props.data.interface_samples.length-1]),rate=(n:number|null)=>n===null?'—':n.toLocaleString(undefined,{maximumFractionDigits:2})
</script>
<template><div class="snmp-results structured"><p v-if="error" class="error">{{error.code}} · {{error.message}}</p><template v-if="data"><h3>SNMP {{data.version}} · {{data.security_level}} · {{data.completion_reason}}</h3><p>{{data.local_endpoint}} → {{data.remote_endpoint}}</p><p>{{t('请求 / 重试 / 响应 / 超时','Requests / retries / responses / timeouts')}}: {{data.stats.requests}} / {{data.stats.retries}} / {{data.stats.responses}} / {{data.stats.timeouts}} · {{t('对象错误','Object errors')}}: {{data.stats.object_errors}}</p><p v-if="data.partial" class="error">{{t('部分结果；请检查停止原因或预算。','Partial result; review stop reason or limits.')}}</p><p v-if="data.engine">Engine {{data.engine.id}} · boots {{data.engine.boots}} · time {{data.engine.time}}</p>
<p v-if="data.varbinds.length>1000">{{t('显示前 1000 项；完整有界结果可导出 JSON。','Showing first 1000 items; export JSON for all bounded results.')}}</p><div v-if="data.varbinds.length" class="table-scroll"><table class="snmp-varbinds"><thead><tr><th>OID</th><th>{{t('类型','Type')}}</th><th>{{t('值 / 对象错误','Value / object error')}}</th></tr></thead><tbody><tr v-for="(v,i) in data.varbinds.slice(0,1000)" :key="i"><td>{{v.oid}}</td><td>{{v.kind}}</td><td>{{v.object_error??v.value}}</td></tr></tbody></table></div>
<template v-if="latest"><p v-if="latest.error" class="error">{{t('本次采样缺失，继续观察','Sample missing; observing continues')}} · {{latest.error}}</p><p>{{t('采样 / 缺口 / 已淘汰快照','Samples / gaps / expired snapshots')}}: {{data.stats.samples}} / {{data.stats.gaps}} / {{data.stats.samples_dropped}} · {{latest.observed_at}} · {{latest.interval_ms??'—'}} ms</p><p>{{t('使用两次有效采样与实际间隔；重启、回绕、计数断点或采样缺口使速率为空。','Rates use valid sample pairs and actual intervals; restart, wrap, discontinuity or gaps clear rates.')}}</p><div class="table-scroll"><table class="snmp-interfaces" style="table-layout:auto;min-width:1080px;width:max-content"><thead><tr><th style="width:160px;min-width:160px">{{t('接口 / 别名','Interface / alias')}}</th><th>{{t('管理 / 运行','Admin / oper')}}</th><th>{{t('速率 bit/s','Speed bit/s')}}</th><th>{{t('入 / 出 bit/s','In / out bit/s')}}</th><th>{{t('计数器 / 断点','Counters / discontinuity')}}</th><th>errors / discards (in / out)</th></tr></thead><tbody><tr v-for="i in latest.interfaces" :key="i.index"><td>{{i.index}} · {{i.name}}<small>{{i.alias}}</small></td><td>{{i.admin_status??'—'}} / {{i.oper_status??'—'}}</td><td>{{i.speed_bps??'—'}}</td><td>{{rate(i.in_bps)}} / {{rate(i.out_bps)}}</td><td>{{i.counter_bits}} bit: {{i.in_octets??'—'}} / {{i.out_octets??'—'}}<small>{{i.discontinuity??'—'}}</small></td><td>{{i.in_errors??'—'}} / {{i.out_errors??'—'}}<small>{{i.in_discards??'—'}} / {{i.out_discards??'—'}}</small></td></tr></tbody></table></div></template>
<details><summary>{{t('范围与限制','Scope and limits')}}</summary><p v-for="(l,i) in data.limitations" :key="i">{{l}}</p><p>{{t('支持数值 OID 和内置名称；没有完整 MIB 编译器。','Numeric OIDs and built-in names; no full MIB compiler.')}}</p></details></template><p v-else>{{t('填写设备与运行凭据，手动开始查询。','Enter the device and runtime credentials, then start a query.')}}</p></div></template>
<style scoped>.snmp-results{min-width:0;overflow-wrap:anywhere}.snmp-results td{white-space:normal;max-width:440px}.snmp-results small{display:block}.snmp-interfaces{min-width:1080px}.snmp-interfaces th,.snmp-interfaces td{min-width:110px}.snmp-interfaces th:first-child,.snmp-interfaces td:first-child{min-width:160px}.snmp-interfaces th:nth-child(5),.snmp-interfaces td:nth-child(5){min-width:230px}</style>
